def stream_rows(resource, transform):
    failed = False
    try:
        while True:
            try:
                row = resource.read_next()
                if row is None:
                    return
                value = transform(row)
            except BaseException:
                failed = True
                raise
            yield value
    finally:
        if failed:
            # Cleanup must not replace an active read or transform error.
            try:
                resource.close()
            except BaseException:
                pass
        else:
            resource.close()
